import React, { useState, useEffect, useRef } from 'react';

import axios from 'axios';

const api = axios.create({
  baseURL: 'http://localhost:5000/api',
  headers: { 'Content-Type': 'application/json' }
});

api.interceptors.request.use(config => {
  const token = localStorage.getItem('token');
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

// Add response interceptor for better error handling
api.interceptors.response.use(
  response => response,
  error => {
    console.error('API Error:', {
      url: error.config?.url,
      method: error.config?.method,
      status: error.response?.status,
      data: error.response?.data
    });
    
    // Show user-friendly error messages
    if (error.response?.status === 404) {
      console.warn('Endpoint not found:', error.config?.url);
    }
    if (error.response?.status === 500) {
      console.error('Server error:', error.response?.data);
    }
    
    return Promise.reject(error);
  }
);

// ==================== HELPER FUNCTIONS ====================

const formatDate = (dateString) => {
  if (!dateString) return 'No date set';
  try {
    const date = new Date(dateString);
    if (isNaN(date.getTime())) return 'Invalid Date';
    
    // Add 3 hours for Kenyan time (UTC+3)
    const kenyanDate = new Date(date.getTime() + (3 * 60 * 60 * 1000));
    
    return kenyanDate.toLocaleDateString('en-KE', {
      timeZone: 'Africa/Nairobi',
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      hour12: false
    });
  } catch (error) {
    console.error('Date formatting error:', error);
    return 'Invalid Date';
  }
};
// Get current Kenyan date (YYYY-MM-DD)
const getKenyanDate = () => {
  const now = new Date();
  // Add 3 hours for Kenyan time (UTC+3)
  const kenyanTime = new Date(now.getTime() + (3 * 60 * 60 * 1000));
  return kenyanTime.toISOString().split('T')[0];
};

// Get current Kenyan datetime for API calls
const getKenyanDateTime = () => {
  const now = new Date();
  const kenyanTime = new Date(now.getTime() + (3 * 60 * 60 * 1000));
  return kenyanTime.toISOString();
};

const formatCurrency = (amount) => {
  return new Intl.NumberFormat('en-KE', {
    style: 'currency',
    currency: 'KES',
    minimumFractionDigits: 0
  }).format(amount || 0);
};

// ==================== GET SCHOOL LOGO OR DEFAULT ====================
const getSchoolLogo = (school) => {
  if (school?.contact?.logo) {
    return school.contact.logo;
  }
 

  return ''; 
};

// ==================== GET SCHOOL NAME FOR PRINTING ====================
const getSchoolNameForPrint = (school) => {
  return school?.name || 'School Name';
};

