// ==================== FIXED GLOBAL GRADE CALCULATION ====================
const calculateGrade = (marks, maxMarks = 100, schoolCategory = 'SENIOR_SECONDARY') => {
  if (!marks && marks !== 0) return { grade: '-', points: 0, remark: '' };
  
  const percentage = (marks / maxMarks) * 100;
  
  console.log('📊 Calculating grade:', { marks, percentage, schoolCategory });
  
  if (schoolCategory === 'UNIVERSITY') {
    // University Grading (A, B, C, D, E)
    if (percentage >= 70) return { grade: 'A', points: 5.0, remark: 'Excellent' };
    if (percentage >= 60) return { grade: 'B', points: 4.0, remark: 'Very Good' };
    if (percentage >= 50) return { grade: 'C', points: 3.0, remark: 'Good' };
    if (percentage >= 40) return { grade: 'D', points: 2.0, remark: 'Fair' };
    return { grade: 'E', points: 1.0, remark: 'Poor' };
  } 
  else if (schoolCategory === 'COLLEGE_TVET') {
    // TVET Grading
    if (percentage >= 80) return { grade: 'DISTINCTION', points: 5, remark: 'Distinction' };
    if (percentage >= 65) return { grade: 'CREDIT', points: 4, remark: 'Credit' };
    if (percentage >= 50) return { grade: 'MERIT', points: 3, remark: 'Merit' };
    if (percentage >= 40) return { grade: 'PASS', points: 2, remark: 'Pass' };
    return { grade: 'FAIL', points: 1, remark: 'Fail' };
  }
  else if (schoolCategory === 'ECDE_PRIMARY_JSS') {
    // CBC Grading
    if (percentage >= 80) return { grade: 'Exceeding Expectations', points: 4, remark: 'Exceeding Expectations' };
    if (percentage >= 65) return { grade: 'Meeting Expectations', points: 3, remark: 'Meeting Expectations' };
    if (percentage >= 50) return { grade: 'Approaching Expectations', points: 2, remark: 'Approaching Expectations' };
    if (percentage >= 30) return { grade: 'Below Expectations', points: 1, remark: 'Below Expectations' };
    return { grade: 'Needs Improvement', points: 0, remark: 'Needs Improvement' };
  }
  else {
    // Kenya 8-4-4 System (Secondary)
    if (percentage >= 80) return { grade: 'A', points: 12, remark: 'Excellent' };
    if (percentage >= 75) return { grade: 'A-', points: 11, remark: 'Very Good' };
    if (percentage >= 70) return { grade: 'B+', points: 10, remark: 'Good' };
    if (percentage >= 65) return { grade: 'B', points: 9, remark: 'Above Average' };
    if (percentage >= 60) return { grade: 'B-', points: 8, remark: 'Average' };
    if (percentage >= 55) return { grade: 'C+', points: 7, remark: 'Below Average' };
    if (percentage >= 50) return { grade: 'C', points: 6, remark: 'Fair' };
    if (percentage >= 45) return { grade: 'C-', points: 5, remark: 'Below Expectations' };
    if (percentage >= 40) return { grade: 'D+', points: 4, remark: 'Needs Improvement' };
    if (percentage >= 35) return { grade: 'D', points: 3, remark: 'Poor' };
    if (percentage >= 30) return { grade: 'D-', points: 2, remark: 'Very Poor' };
    return { grade: 'E', points: 1, remark: 'Needs Intervention' };
  }
};
// FIXED: Calculate points from grade with null checks
const calculatePointsFromGrade = (grade, system = 'KENYA_844') => {
  if (!grade) return '';
  
  const gradingSystem = GRADING_SYSTEMS[system] || GRADING_SYSTEMS.KENYA_844;
  
  // Try to find by grade value
  for (const [gradeKey, gradeInfo] of Object.entries(gradingSystem.grading)) {
    if (gradeInfo.grade === grade || gradeKey === grade) {
      return gradeInfo.points || '';
    }
  }
  
  return '';
};

// FIXED: Calculate GPA from grades with null checks
const calculateGPA = (grades, credits, system = 'UNIVERSITY') => {
  if (!grades || !Array.isArray(grades) || grades.length === 0) return 0;
  
  const gradingSystem = GRADING_SYSTEMS[system] || GRADING_SYSTEMS.UNIVERSITY;
  
  let totalPoints = 0;
  let totalCredits = 0;
  
  grades.forEach((grade, index) => {
    const credit = (credits && credits[index]) || 3;
    let gpaValue = 0;
    
    // Find GPA value for this grade
    for (const [gradeKey, gradeInfo] of Object.entries(gradingSystem.grading)) {
      if (gradeInfo.grade === grade || gradeKey === grade) {
        gpaValue = gradeInfo.gpa || 0;
        break;
      }
    }
    
    totalPoints += gpaValue * credit;
    totalCredits += credit;
  });
  
  return totalCredits > 0 ? (totalPoints / totalCredits).toFixed(2) : 0;
};

// ==================== UI COMPONENTS ====================

const InputField = ({ label, type = 'text', value, onChange, required, placeholder, min, max, step, textarea, rows, disabled }) => {
  const inputValue = type === 'number' && (value === '' || isNaN(value)) ? '' : value;
  
  if (textarea) {
    return (
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-1">{label}</label>
        <textarea 
          className="w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500" 
          value={value || ''} 
          onChange={onChange} 
          required={required}
          placeholder={placeholder}
          rows={rows || 3}
          disabled={disabled}
        />
      </div>
    );
  }
  
  return (
    <div>
      <label className="block text-sm font-medium text-gray-700 mb-1">{label}</label>
      <input 
        type={type} 
        className="w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500" 
        value={inputValue} 
        onChange={onChange} 
        required={required}
        placeholder={placeholder}
        min={min}
        max={max}
        step={step}
        disabled={disabled}
      />
    </div>
  );
};

const SelectField = ({ label, value, onChange, options, placeholder, disabled }) => {
  const safeValue = (value === undefined || value === null || Number.isNaN(value)) ? '' : String(value);
  
  return (
    <div>
      {label && <label className="block text-sm font-medium text-gray-700 mb-1">{label}</label>}
      <select 
        className="w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500" 
        value={safeValue} 
        onChange={onChange}
        disabled={disabled}
      >
        <option value="">{placeholder || `Select ${label}`}</option>
        {options.map((opt, index) => {
          const optValue = typeof opt === 'string' ? opt : opt.value;
          const optLabel = typeof opt === 'string' ? opt : opt.label;
          const optKey = opt.id || optValue || `option-${index}`;
          const safeOptValue = (optValue === undefined || optValue === null || Number.isNaN(optValue)) ? '' : String(optValue);
          return (
            <option key={optKey} value={safeOptValue}>
              {optLabel}
            </option>
          );
        })}
      </select>
    </div>
  );
};

const SearchableSelect = ({ label, value, onChange, options, placeholder, disabled }) => {
  const [search, setSearch] = useState('');
  const [isOpen, setIsOpen] = useState(false);
  
  const filteredOptions = options.filter(opt => opt.label.toLowerCase().includes(search.toLowerCase()));
  const selectedOption = options.find(opt => opt.value === value);
  
  return (
    <div className="relative">
      {label && <label className="block text-sm font-medium text-gray-700 mb-1">{label}</label>}
      <div className="relative">
        <input
          type="text"
          className="w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500 cursor-pointer"
          value={search || selectedOption?.label || ''}
          onChange={(e) => setSearch(e.target.value)}
          onFocus={() => setIsOpen(true)}
          onBlur={() => setTimeout(() => setIsOpen(false), 200)}
          placeholder={placeholder || `Search ${label}...`}
          disabled={disabled}
        />
        <i className="fas fa-chevron-down absolute right-3 top-3 text-gray-400"></i>
      </div>
      
      {isOpen && !disabled && (
        <div className="absolute z-50 w-full mt-1 bg-white border rounded-lg shadow-lg max-h-60 overflow-auto">
          {filteredOptions.length > 0 ? (
            filteredOptions.map(opt => (
              <div
                key={opt.value}
                className="px-3 py-2 hover:bg-indigo-50 cursor-pointer"
                onClick={() => { onChange({ target: { value: opt.value } }); setSearch(''); setIsOpen(false); }}
              >
                <div className="font-medium">{opt.label}</div>
                {opt.subLabel && <div className="text-xs text-gray-500">{opt.subLabel}</div>}
              </div>
            ))
          ) : (
            <div className="px-3 py-2 text-gray-500">No results found</div>
          )}
        </div>
      )}
    </div>
  );
};
