  // ==================== SEARCHABLE SELECT COMPONENT ====================
  const SearchableSelect = ({ label, value, onChange, options, placeholder, disabled }) => {
    const [search, setSearch] = useState('');
    const [isOpen, setIsOpen] = useState(false);
    
    const filteredOptions = React.useMemo(() => {
      if (!search) return options;
      return options.filter(opt => 
        opt.label?.toLowerCase().includes(search.toLowerCase()) ||
        opt.subLabel?.toLowerCase().includes(search.toLowerCase())
      );
    }, [options, search]);
    
    const selectedOption = options.find(opt => opt.value === value);
    
    return (
      <div className="relative">
        {label && <label className="block text-sm font-medium text-gray-700 mb-1">{label}</label>}
        <div className="relative">
          <input
            type="text"
            className="w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500 cursor-pointer"
            value={search || selectedOption?.label || ''}
            onChange={(e) => setSearch(e.target.value)}
            onFocus={() => setIsOpen(true)}
            onBlur={() => setTimeout(() => setIsOpen(false), 200)}
            placeholder={placeholder || `Search ${label}...`}
            disabled={disabled}
          />
          <i className="fas fa-chevron-down absolute right-3 top-3 text-gray-400"></i>
        </div>
        
        {isOpen && !disabled && (
          <div className="absolute z-50 w-full mt-1 bg-white border rounded-lg shadow-lg max-h-60 overflow-auto">
            {filteredOptions.length > 0 ? (
              filteredOptions.map(opt => (
                <div
                  key={opt.value}
                  className="px-3 py-2 hover:bg-indigo-50 cursor-pointer border-b last:border-b-0"
                  onClick={() => { 
                    onChange({ target: { value: opt.value } }); 
                    setSearch(''); 
                    setIsOpen(false); 
                  }}
                >
                  <div className="font-medium">{opt.label}</div>
                  {opt.subLabel && <div className="text-xs text-gray-500">{opt.subLabel}</div>}
                </div>
              ))
            ) : (
              <div className="px-3 py-2 text-gray-500">No results found</div>
            )}
          </div>
        )}
      </div>
    );
  };

